SECRET_KEYS = [
    "api_key",
    "app_password",
    "credentials_json",
    "token",
    "password",
    "secret",
    "apikey",
]


def _inferir_tipo_credencial(config: dict) -> str:
    """Infiere el tipo de credencial basado en las claves presentes."""
    if "credentials_json" in config:
        return "json"
    if "username" in config and ("password" in config or "app_password" in config):
        return "basic"
    if "api_key" in config or "apikey" in config:
        return "api_key"
    if "token" in config:
        return "bearer"
    return "api_key"


def _extraer_secreto(config: dict) -> tuple[str | None, str]:
    """Extrae el primer valor de secreto encontrado y devuelve (clave_encontrada, valor)."""
    for key in SECRET_KEYS:
        if key in config and config[key]:
            return key, str(config[key])
    return None, ""


def migrar_secretos_herramientas(apps, schema_editor):
    """Migra secretos desde Herramienta.configuracion a Credencial.

    Idempotente: usa slug derivado del slug de la herramienta para evitar duplicados.
    Solo crea Credencial si la herramienta tiene secretos en su configuración.
    """
    Herramienta = apps.get_model("core", "Herramienta")
    Credencial = apps.get_model("core", "Credencial")

    for herramienta in Herramienta.objects.all():
        config = dict(herramienta.configuracion or {})
        if not config:
            continue

        clave_secreta, valor_secreto = _extraer_secreto(config)
        if not valor_secreto:
            continue  # No hay secretos, nada que migrar

        # Determinar tipo de credencial
        tipo = _inferir_tipo_credencial(config)

        # Metadata: todo lo que no sea secreto
        metadata = {k: v for k, v in config.items() if k not in SECRET_KEYS}

        # Slug único para la credencial (idempotente)
        cred_slug = f"auto-gen-{herramienta.slug}"

        with transaction.atomic():
            credencial, _ = Credencial.objects.get_or_create(
                slug=cred_slug,
                defaults={
                    "nombre": f"{herramienta.nombre} (auto-generada)",
                    "tipo": tipo,
                    "secreto_cifrado": valor_secreto,
                    "metadata": metadata,
                    "es_sistema": herramienta.es_sistema,
                },
            )

            # Limpiar configuración de la herramienta (quitar secretos)
            config_limpia = {k: v for k, v in config.items() if k not in SECRET_KEYS}
            herramienta.configuracion = config_limpia
            herramienta.credencial = credencial
            herramienta.save(update_fields=["configuracion", "credencial"])


